/* 13 Oct 2026: the twelve months roll with the reader's own clock, ending at
   the current month, so presets such as Last 3 months always mean "up to
   today". The sample figures are unchanged; only their months move. */
const _TD=new Date(), _MN=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const _MD=[...Array(12)].map((_,k)=>new Date(_TD.getFullYear(),_TD.getMonth()-11+k,1));
const MONTH_LABELS=_MD.map(d=>_MN[d.getMonth()]);
